{"jobs": [{"absolute_url": "https://careers.duolingo.com/jobs/8745752002?gh_jid=8745752002", "data_compliance": [{"type": "gdpr", "requires_consent": false, "requires_processing_consent": false, "requires_retention_consent": false, "retention_period": null, "demographic_data_consent_applies": false}], "internal_job_id": 6497583002, "location": {"name": "Pittsburgh, PA"}, "metadata": [{"id": 10945305002, "name": "Division", "value": "Engineering", "value_type": "single_select"}, {"id": 9700632002, "name": "Req Type", "value": "Industry", "value_type": "single_select"}, {"id": 98443292002, "name": "Featured Title", "value": null, "value_type": "short_text"}, {"id": 98445720002, "name": "Featured City Name", "value": null, "value_type": "single_select"}], "id": 8745752002, "updated_at": "2026-08-25T12:16:35-04:00", "requisition_id": "1258", "title": "Senior Android Engineer, Client Platform - Application Stability and Performance", "company_name": "Duolingo", "first_published": "2026-08-25T09:19:51-04:00", "language": "en", "application_deadline": null, "content": "&lt;p&gt;Our mission at Duolingo is to develop the best education in the world and make it universally available. It’s a big mission, and that’s where you come in!&lt;/p&gt;
&lt;p&gt;At Duolingo, you’ll join a team that cares about finding &lt;a href=&quot;https://blog.duolingo.com/tag/engineering/?utm_source=greenhouse.com&amp;amp;utm_medium=referral&amp;amp;utm_campaign=engblog_gh_091224&quot;&gt;innovative solutions to complex technical problems&lt;/a&gt;, running countless experiments (300+ at a time!) with our massive user base to make data-driven decisions, and educating our users and employees alike. You’ll have limitless learning opportunities, mentorship and collaboration with world-class minds, and a variety of projects with large scopes — while doing work that’s both fun and meaningful.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Join our life-changing mission to develop education for our half a billion (and growing!) learners around the world.&lt;/p&gt;
&lt;hr&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;About the role...&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As an Android engineer on our Application Stability and Performance team you’ll own the stability and performance of the Duolingo Android Learning app for millions of learners.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This team builds the tooling other engineers depend on to keep the app performant like AI agent driven crash and memory analysis, coroutine system tracing, and Macrobenchmark suites that catch regressions before they ship. You&#39;ll also own the performance metrics that feed into our experiment analyses and help ensure hundreds of concurrent experiments surface any performance issues or regressions.&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;🧠&amp;nbsp; You will...&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Lead architectural initiatives to fix the slowest parts of the app, from startup to critical learning flows&lt;/li&gt;
&lt;li&gt;Own and evolve our performance tooling with tracing, benchmarking, and automated regression detection&lt;/li&gt;
&lt;li&gt;Serve as a bridge between Client Platform and Product feature teams, helping them understand and act on the performance data we provide&lt;/li&gt;
&lt;li&gt;Foster a culture of engineering excellence around performance and mentor engineers of all experience levels&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;✅&amp;nbsp; You have...&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Worked on and shipped large scale Android applications&lt;/li&gt;
&lt;li&gt;Experience identifying the root cause and resolving ANRs, memory leaks, dropped frames, and complex crashes&lt;/li&gt;
&lt;li&gt;Strong Kotlin skills and deep familiarity with coroutines, Jetpack Compose, and modern architecture patterns&lt;/li&gt;
&lt;li&gt;Experience optimizing startup time, memory, and network usage for low-memory devices&lt;/li&gt;
&lt;li&gt;Strong problem-solving skills and a passion for tackling difficult challenges&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;⭐&amp;nbsp; Exceptional candidates will have...&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Expertise in Android tracing tooling like the AndroidX Tracing Library and Perfetto&lt;/li&gt;
&lt;li&gt;Experience with crash observability tooling like Sentry and Android Vitals&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;em&gt;The offered salary is dependent upon several factors, including work experience, skills, and internal peer comparisons. The posted range is subject to change in the future. For this role, base salary is supplemented by equity compensation. We encourage you to talk with your recruiter for more information related to compensation for this role!&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range: &lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$182,800&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$247,300 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p class=&quot;Z7ph2&quot;&gt;&lt;strong&gt;Benefits:&lt;/strong&gt; Take a peek at how we care for our employees&#39; holistic well-being with our benefits &lt;a href=&quot;https://careers.duolingo.com/#benefits&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Job Alerts:&lt;/strong&gt; Sign up for job alerts &lt;a href=&quot;http://my.greenhouse.io/users/sign_in?job_board=duolingo&quot;&gt;here&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Accommodations: &lt;/strong&gt;We will do everything we can within reason to make sure that your interview takes place in an environment that fairly and accurately assesses your skills. If you need assistance or accommodation, please contact &lt;a href=&quot;mailto:accommodations@duolingo.com&quot;&gt;accommodations@duolingo.com&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Equal Employment Opportunity: &lt;/strong&gt;Duolingo is proud to be an Equal Employment Opportunity employer. We do not discriminate based upon race, religion, color, national origin, gender (including pregnancy, childbirth, or related medical conditions), sexual orientation, gender identity, gender expression, age, status as a protected veteran, status as an individual with a disability, or other applicable legally protected characteristics.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Fraud Warning: &lt;/strong&gt;Unfortunately, there is a rise in scammers pretending to be real Duolingo employees. Duolingo and our employees will never ask for your Social Security number, bank details, or passport info, and we’ll never ask you to deposit a check, purchase equipment, or exchange money during the interview process. Real Duolingo employees always use an email that ends in @duolingo.com or @recruiting.duolingo.com. Stay alert and double-check these details before sharing any information.&lt;br&gt;&lt;br&gt;By applying for this position your data will be processed as per the&lt;a href=&quot;https://docs.google.com/document/d/e/2PACX-1vTX9GKeRMOMA9Vtm0vfGibrYPYz8ysl0Dg8KSXgj_PxeT5ChsdnNZZWtpxu4t7xillTPGnngnKCjIbV/pub&quot;&gt; Duolingo Applicant Privacy Notice&lt;/a&gt;.&lt;br&gt;&lt;br&gt;&lt;/p&gt;&lt;/div&gt;", "departments": [{"id": 4089876002, "name": "Engineering", "child_ids": [4034814002, 4034813002, 4047599002, 4089877002, 4034085002, 4034796002, 4034810002, 4034809002, 4038852002, 4034797002, 4034812002, 4034811002, 4034816002], "parent_id": null}], "offices": [{"id": 4017771002, "name": "Pittsburgh, PA", "location": "Pittsburgh, Pennsylvania, United States", "child_ids": [], "parent_id": null}], "ai_disclaimer": "<p><strong style="font-size: 14px;">AI in Hiring: </strong><span style="font-size: 14px;">Duolingo uses AI technology to assist in our hiring process. We want to be transparent about how we use this technology and your rights. We use Greenhouse Software's Talent Matching feature to assist with reviewing applications for the skills and experience we have decided are important for this role.</span></p><p><br></p><p><strong style="font-size: 14px;">How it works:</strong><span style="font-size: 14px;"> </span></p><ol><li data-list="bullet"><span class="ql-ui"></span>Talent Matching reviews your resume and responses to application questions to determine the extent to which your qualifications match the job requirements selected for this role. These requirements and their desired weighting are established by our recruiters in collaboration with hiring managers.</li><li data-list="bullet"><span class="ql-ui"></span>All Talent Matching output is reviewed by our recruiting and hiring teams, who make the final decision on each application. Talent Matching does not automatically disposition any candidate or make hiring decisions.</li></ol>", "include_ai_disclaimer": true, "ai_opt_out_request_url": "http://app2.greenhouse.io/ai_opt_out_request/job_post/8745752002/ai_opt_out"}]}
